import React from "react";
import type { PageProps } from "gatsby";
import { CmsShell, DashboardView } from "../ppm/cfimages/CmsShell";
import { imageApi } from "../ppm/cfimages/imageApi";

const DashboardPage: React.FC<PageProps> = ({ location }) => (
  <CmsShell pathname={location.pathname}>
    {({ onMenuToggle }) => (
      <DashboardView api={imageApi} onMenuToggle={onMenuToggle} />
    )}
  </CmsShell>
);

export default DashboardPage;
